package com.agrolink.controller;import com.agrolink.dto.notification.*;import com.agrolink.service.NotificationService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController{private final NotificationService s;public NotificationController(NotificationService s){this.s=s;}@GetMapping public List<NotificationResponse> mine(Authentication a){return s.mine(a.getName());}@PutMapping("/{id}/read") public NotificationResponse read(Authentication a,@PathVariable Long id){return s.markRead(a.getName(),id);}}
